package hu.synostream.android;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;
public class SelfAudit0527Test {
 @Test public void allBrowsableFormatsCanBeDeleted()throws Exception{for(String ext:List.of(".mkv",".mp4",".avi",".m4v",".mov",".wmv",".ts",".mts",".m2ts",".mpg",".mpeg",".webm")){String file=MediaDeletionTest.ROOT+"/Movie/Movie"+ext;assertTrue(MediaLogic.video(file));assertTrue("Deletion misses "+ext,MediaDeletion.video(file));MediaDeletionTest.Files fs=new MediaDeletionTest.Files(file,MediaDeletionTest.ROOT+"/Movie/release.nfo");MediaDeletion inv=new MediaDeletionTest().movie(fs,file);MediaDeletion.Plan p=inv.plan(null);assertTrue(p.files.contains(file));assertTrue(p.files.contains(MediaDeletionTest.ROOT+"/Movie/release.nfo"));}}
 @Test public void barePrivateAddressesUseDsmLocalDefaultPort(){for(String host:List.of("192.168.1.2","nas.local","[fd00::1]")){NasClient.Credentials c=new NasClient.Credentials("",host,"","","fixture","fixture","");assertEquals("http://"+host+":5000",NasRoutes.plan(c,true).get(0).value);}NasClient.Credentials primary=new NasClient.Credentials("192.168.1.2","","fixture","fixture","");assertEquals("http://192.168.1.2:5000",NasRoutes.plan(primary,true).get(0).value);}
 @Test public void explicitUrlsAndDdnsDefaultsArePreserved(){for(String url:List.of("https://nas.local","http://192.168.1.2","https://nas.local:5001","http://192.168.1.2:1234")){NasClient.Credentials c=new NasClient.Credentials("",url,"","","fixture","fixture","");assertEquals(url,NasRoutes.plan(c,true).get(0).value);}assertEquals("https://nas.example.org",NasRoutes.plan(new NasClient.Credentials("nas.example.org","","fixture","fixture",""),true).get(0).value);}
}
